import { sql } from 'drizzle-orm';
import { integer, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Time-ordered UUID primary key, generated by PostgreSQL 18's built-in uuidv7(). */
export const idColumn = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

/** created_at / updated_at; updated_at is maintained by a database trigger. */
export const timestamps = () => ({
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});

/** Optimistic concurrency counter: updates must match the version they read (api.md §8). */
export const versionColumn = () => integer('version').notNull().default(1);
